class Solution {
    fun sampleStats(count:IntArray):DoubleArray{
        var minimum=-1;
        var maximum=0;
        var mode=0;
        var total=0;
        var sum=0L;
        for(value in count.indices)if(count[value]>0){
            if(minimum<0)minimum=value;
            maximum=value;
            total+=count[value];
            sum+=value.toLong()*count[value];
            if(count[value]>count[mode])mode=value
        };
        fun kth(rank:Int):Int{
            var cumulative=0;
            for(value in count.indices){
                cumulative+=count[value];
                if(cumulative>=rank)return value
            };
            return -1
        };
        val median=(kth((total+1)/2)+kth((total+2)/2))/2.0;
        return doubleArrayOf(minimum.toDouble(),maximum.toDouble(),sum.toDouble()/total,median,mode.toDouble())
    }
}

